const buf = Buffer.from("Node");
console.log(buf.toString("hex"));                      // 4e6f6465
console.log(buf.toString("base64"));                   // Tm9kZQ==

// base64url: biến thể an toàn cho URL (dùng trong JWT): thay + / bằng - _ và bỏ dấu =
const toUrl = (b64) => b64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
console.log(toUrl("Tm9kZQ=="));

